//! Runtime for inflection crates generated by morphe from Wiktionary.
//!
//! A generated crate holds its trained model as bytes and calls into this
//! crate to answer queries. Everything here is a table walk: no I/O, no
//! dependencies.

pub mod codec;
pub mod edit;
pub mod model;

pub use edit::Edit;
pub use model::{Analysis, Model, Options};

/// Candidates with confidences, best first.
pub type Scored<T> = Vec<(T, f32)>;
